CREATE OR REPLACE FUNCTION customers.reject_erased_customer_recreation() RETURNS trigger AS $$
BEGIN
  IF EXISTS(
    SELECT 1 FROM customers.erasure_requests
    WHERE merchant_id=NEW.merchant_id AND customer_id=NEW.id
  ) THEN
    RAISE EXCEPTION 'customer has an erasure request';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

