export async function customerIsActive(
  client: PoolClient,
  merchantId: string,
  customerId: string,
): Promise<boolean> {
  const result = await client.query(
    `SELECT 1 FROM customers.customers WHERE merchant_id=$1 AND id=$2 AND status='active'`,
    [merchantId, customerId],
  );
  return Boolean(result.rowCount);
}

export function customerIdFromEvent(event: {
  aggregateType: string;
  aggregateId: string;
  payload: Record<string, unknown>;
}): string | undefined {
  return typeof event.payload.customerId === 'string'
    ? event.payload.customerId
    : event.aggregateType === 'customer' ? event.aggregateId : undefined;
}
