{"command":"create","path":"/workspace/source/apps/customer-service/src/erasure-repository.ts","file_text":"import type { PoolClient } from 'pg';
import { pool, transaction } from '../../../packages/database/src/pool.js';
import { lockCustomer } from '../../../packages/operations/src/customer-privacy.js';

export interface ErasureRequestRow {
  id: string;
  merchant_id: string;
  customer_id: string;
  status: 'pending' | 'processing' | 'failed' | 'completed';
  attempts: number;
  artifact_keys: string[];
  created_at: Date;
  updated_at: Date;
  completed_at: Date | null;
  last_error: string | null;
}

export class ErasureRepository {
  async createOrResume(merchantId: string, customerId: string, key: string): Promise<ErasureRequestRow> {
    return await transaction(async (client) => {
      await client.query(`SELECT pg_advisory_xact_lock(hashtextextended($1,0))`, [`erasure-key:${merchantId}:${key}`]);
      await lockCustomer(client, merchantId, customerId);

      const binding = await client.query<{ customer_id: string; request_id: string }>(
        `SELECT customer_id,request_id FROM customers.erasure_idempotency_keys
         WHERE merchant_id=$1 AND key=$2`,
        [merchantId, key],
      );
      if (binding.rows[0] && binding.rows[0].customer_id !== customerId) {
        throw Object.assign(new Error('idempotency_key_conflict'), { statusCode: 409 });
      }

      let request = await this.findForCustomer(client, merchantId, customerId);
      if (binding.rows[0] && !request) {
        throw new Error('erasure idempotency binding is invalid');
      }
      if (!request) {
        const customer = await client.query(
          `SELECT 1 FROM customers.customers WHERE merchant_id=$1 AND id=$2 FOR UPDATE`,
          [merchantId, customerId],
        );
        if (!customer.rowCount) throw Object.assign(new Error('customer_not_found'), { statusCode: 404 });
        const inserted = await client.query<ErasureRequestRow>(
          `INSERT INTO customers.erasure_requests(merchant_id,customer_id)
           VALUES($1,$2) RETURNING *`,
          [merchantId, customerId],
        );
        request = inserted.rows[0]!;
        await client.query(
          `UPDATE customers.customers SET status='erasing',version=version+1,updated_at=now()
           WHERE merchant_id=$1 AND id=$2`,
          [merchantId, customerId],
        );
      } else if (request.status === 'failed') {
        const resumed = await client.query<ErasureRequestRow>(
          `UPDATE customers.erasure_requests
           SET status='pending',available_at=now(),last_error=NULL,updated_at=now()
           WHERE id=$1 RETURNING *`,
          [request.id],
        );
        request = resumed.rows[0]!;
      }

      if (!binding.rows[0]) {
        await client.query(
          `INSERT INTO customers.erasure_idempotency_keys(merchant_id,key,customer_id,request_id)
           VALUES($1,$2,$3,$4)`,
          [merchantId, key, customerId, request.id],
        );
      }
      return request;
    });
  }

  async find(merchantId: string, requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId],
    );
    return result.rows[0];
  }

  async claim(workerId: string): Promise<ErasureRequestRow | undefined> {
    return await transaction(async (client) => {
      const result = await client.query<ErasureRequestRow>(
        `UPDATE customers.erasure_requests request
         SET status='processing',attempts=request.attempts+1,locked_by=$1,locked_at=now(),
             lease_expires_at=now()+interval '2 minutes',last_error=NULL,updated_at=now()
         WHERE request.id=(SELECT id FROM customers.erasure_requests
           WHERE ((status IN ('pending','failed') AND available_at<=now())
             OR (status='processing' AND lease_expires_at<now()))
           ORDER BY available_at,created_at FOR UPDATE SKIP LOCKED LIMIT 1)
         RETURNING *`,
        [workerId],
      );
      return result.rows[0];
    });
  }

  async saveArtifactKeys(requestId: string, keys: string[]): Promise<void> {
    await pool.query(
      `UPDATE customers.erasure_requests SET artifact_keys=$2,updated_at=now() WHERE id=$1`,
      [requestId, keys],
    );
  }

  async fail(request: ErasureRequestRow): Promise<void> {
    const delay = Math.min(300, 2 ** Math.min(request.attempts, 8));
    await pool.query(
      `UPDATE customers.erasure_requests
       SET status='failed',available_at=now()+($2 || ' seconds')::interval,last_error='cleanup_failed',
           locked_by=NULL,locked_at=NULL,lease_expires_at=NULL,updated_at=now()
       WHERE id=$1`,
      [request.id, delay],
    );
  }

  private async findForCustomer(
    client: PoolClient,
    merchantId: string,
    customerId: string,
  ): Promise<ErasureRequestRow | undefined> {
    const result = await client.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests
       WHERE merchant_id=$1 AND customer_id=$2 FOR UPDATE`,
      [merchantId, customerId],
    );
    return result.rows[0];
  }
}
