{"command":"create","path":"/workspace/source/apps/customer-service/src/erasure-service.ts","file_text":"import { randomUUID } from 'node:crypto';
import { Redis } from 'ioredis';
import type { PoolClient } from 'pg';
import { config } from '../../../packages/config/src/index.js';
import { transaction } from '../../../packages/database/src/pool.js';
import { deleteMailpitMessagesForRecipient } from '../../../packages/notifications/src/mailpit.js';
import { logger } from '../../../packages/observability/src/logger.js';
import { lockCustomer } from '../../../packages/operations/src/customer-privacy.js';
import { CUSTOMER_INDEX, searchClient } from '../../../packages/search/src/client.js';
import { DOCUMENT_BUCKET, objectStore } from '../../../packages/storage/src/minio.js';
import { ErasureRepository, type ErasureRequestRow } from './erasure-repository.js';

interface CleanupTarget {
  emailDestinations: string[];
  artifactKeys: string[];
}

export function presentErasureRequest(row: ErasureRequestRow): Record<string, unknown> {
  return {
    id: row.id,
    customerId: row.customer_id,
    status: row.status,
    attempts: row.attempts,
    createdAt: row.created_at.toISOString(),
    updatedAt: row.updated_at.toISOString(),
    completedAt: row.completed_at?.toISOString() ?? null,
    lastError: row.last_error,
  };
}

export class ErasureService {
  private readonly workerId = `customer-erasure-${randomUUID()}`;
  private readonly redis = new Redis(config().REDIS_URL);

  constructor(private readonly repository = new ErasureRepository()) {}

  async create(merchantId: string, customerId: string, key: string): Promise<Record<string, unknown>> {
    return presentErasureRequest(await this.repository.createOrResume(merchantId, customerId, key));
  }

  async find(merchantId: string, requestId: string): Promise<Record<string, unknown> | undefined> {
    const request = await this.repository.find(merchantId, requestId);
    return request ? presentErasureRequest(request) : undefined;
  }

  async run(signal: AbortSignal): Promise<void> {
    try {
      while (!signal.aborted) {
        const request = await this.repository.claim(this.workerId);
        if (!request) {
          await new Promise((resolve) => setTimeout(resolve, 250));
          continue;
        }
        try {
          const target = await this.prepare(request);
          await this.removeExternalData(request, target);
          await this.completeDatabaseErasure(request);
        } catch (error) {
          logger.error({ error, erasureRequestId: request.id }, 'customer erasure failed');
          await this.repository.fail(request);
        }
      }
    } finally {
      await this.redis.quit();
    }
  }

  private async prepare(request: ErasureRequestRow): Promise<CleanupTarget> {
    return await transaction(async (client) => {
      await lockCustomer(client, request.merchant_id, request.customer_id);
      const customer = await client.query<{ email: string }>(
        `SELECT email FROM customers.customers WHERE merchant_id=$1 AND id=$2 FOR UPDATE`,
        [request.merchant_id, request.customer_id],
      );
      const destinations = await client.query<{ destination: string }>(
        `SELECT destination FROM operations.email_deliveries WHERE merchant_id=$1 AND customer_id=$2
         UNION SELECT destination FROM operations.notifications WHERE merchant_id=$1 AND customer_id=$2
         UNION SELECT destination FROM operations.notification_preferences WHERE merchant_id=$1 AND customer_id=$2`,
        [request.merchant_id, request.customer_id],
      );
      const artifacts = await client.query<{ object_key: string }>(
        `SELECT object_key FROM operations.document_manifests WHERE merchant_id=$1 AND customer_id=$2`,
        [request.merchant_id, request.customer_id],
      );
      await client.query(
        `UPDATE operations.email_deliveries
         SET status=CASE WHEN status='delivered' THEN status ELSE 'cancelled' END,
             cancelled_at=CASE WHEN status='delivered' THEN cancelled_at ELSE now() END,
             locked_by=NULL,locked_at=NULL,lease_expires_at=NULL,last_error=NULL
         WHERE merchant_id=$1 AND customer_id=$2`,
        [request.merchant_id, request.customer_id],
      );
      await client.query(
        `UPDATE operations.notifications
         SET status=CASE WHEN status='delivered' THEN status ELSE 'cancelled' END,updated_at=now(),last_error=NULL
         WHERE merchant_id=$1 AND customer_id=$2`,
        [request.merchant_id, request.customer_id],
      );
      return {
        emailDestinations: [...new Set([
          customer.rows[0]?.email,
          ...destinations.rows.map((row) => row.destination),
        ].filter((value): value is string => Boolean(value)))],
        artifactKeys: artifacts.rows.map((row) => row.object_key),
      };
    });
  }

  private async removeExternalData(request: ErasureRequestRow, target: CleanupTarget): Promise<void> {
    for (const destination of target.emailDestinations) await deleteMailpitMessagesForRecipient(destination);
    for (const key of target.artifactKeys) await objectStore.removeObject(DOCUMENT_BUCKET, key);
    await Promise.all([
      this.redis.del(
        `merchant:${request.merchant_id}:customer:${request.customer_id}`,
        `merchant:${request.merchant_id}:customer:${request.customer_id}:activity`,
      ),
      searchClient.delete({
        index: CUSTOMER_INDEX,
        id: `${request.merchant_id}:${request.customer_id}`,
        refresh: true,
      }).catch((error: unknown) => {
        if ((error as { statusCode?: number }).statusCode !== 404) throw error;
      }),
    ]);
  }

  private async completeDatabaseErasure(request: ErasureRequestRow): Promise<void> {
    await transaction(async (client) => {
      await lockCustomer(client, request.merchant_id, request.customer_id);
      const paymentIds = await client.query<{ id: string }>(
        `SELECT id FROM payments.payment_intents WHERE merchant_id=$1 AND customer_id=$2 FOR UPDATE`,
        [request.merchant_id, request.customer_id],
      );
      const ids = paymentIds.rows.map((row) => row.id);
      await this.scrubCustomerRecords(client, request);
      await this.scrubFinancialRecords(client, request, ids);
      await this.scrubOperationalRecords(client, request, ids);
      await client.query(
        `DELETE FROM customers.customers WHERE merchant_id=$1 AND id=$2`,
        [request.merchant_id, request.customer_id],
      );
      await client.query(
        `UPDATE customers.erasure_requests
         SET status='completed',completed_at=now(),updated_at=now(),last_error=NULL,
             locked_by=NULL,locked_at=NULL,lease_expires_at=NULL
         WHERE id=$1`,
        [request.id],
      );
    });
  }

  private async scrubCustomerRecords(client: PoolClient, request: ErasureRequestRow): Promise<void> {
    const values = [request.merchant_id, request.customer_id];
    await client.query(
      `UPDATE customers.support_tickets SET subject='Customer support conversation'
       WHERE merchant_id=$1 AND id IN(
         SELECT ticket_id FROM customers.support_participants WHERE customer_id=$2
       )`,
      values,
    );
    await client.query(
      `UPDATE customers.support_messages
       SET author_type='deleted_customer',author_id=NULL,body='[deleted]',attachments='[]'
       WHERE merchant_id=$1 AND author_id=$2`,
      values,
    );
    await client.query(`DELETE FROM customers.support_participants WHERE customer_id=$2`, values);
    await client.query(`DELETE FROM customers.addresses WHERE merchant_id=$1 AND customer_id=$2`, values);
    await client.query(`DELETE FROM customers.contacts WHERE merchant_id=$1 AND customer_id=$2`, values);
    await client.query(`DELETE FROM customers.payment_method_refs WHERE merchant_id=$1 AND customer_id=$2`, values);
    await client.query(`DELETE FROM customers.provider_customer_mappings WHERE merchant_id=$1 AND customer_id=$2`, values);
    await client.query(`DELETE FROM provider_sandbox.customers WHERE merchant_id=$1 AND payflow_customer_id=$2`, values);
  }

  private async scrubFinancialRecords(
    client: PoolClient,
    request: ErasureRequestRow,
    paymentIds: string[],
  ): Promise<void> {
    const values = [request.merchant_id, request.customer_id];
    await client.query(
      `UPDATE payments.payment_intents
       SET customer_id=NULL,payment_method_id=NULL,description=NULL,customer_snapshot='{"deleted":true}'
       WHERE merchant_id=$1 AND customer_id=$2`,
      values,
    );
    await client.query(
      `UPDATE payments.payment_attempts SET request_payload='{}',response_payload=COALESCE(response_payload,'{}') - 'customer'
       WHERE merchant_id=$1 AND payment_intent_id=ANY($2::uuid[])`,
      [request.merchant_id, paymentIds],
    );
    await client.query(
      `UPDATE payments.refunds SET customer_email=NULL,reason='customer_requested'
       WHERE merchant_id=$1 AND payment_intent_id=ANY($2::uuid[])`,
      [request.merchant_id, paymentIds],
    );
    await client.query(
      `UPDATE payments.invoices SET customer_id=NULL,billing_snapshot='{"deleted":true}'
       WHERE merchant_id=$1 AND customer_id=$2`,
      values,
    );
    await client.query(
      `UPDATE provider_sandbox.payment_intents
       SET payment_method_id=NULL,provider_customer_id=NULL
       WHERE merchant_id=$1 AND payment_id=ANY($2::uuid[])`,
      [request.merchant_id, paymentIds],
    );
  }

  private async scrubOperationalRecords(
    client: PoolClient,
    request: ErasureRequestRow,
    paymentIds: string[],
  ): Promise<void> {
    const values = [request.merchant_id, request.customer_id];
    await client.query(
      `UPDATE platform.audit_logs SET target_id=NULL,metadata='{}'
       WHERE merchant_id=$1 AND target_type='customer' AND target_id=$2::text`,
      values,
    );
    await client.query(
      `UPDATE operations.outbox_events SET payload='{}'
       WHERE merchant_id=$1 AND (aggregate_id=$2 OR payload->>'customerId'=$2::text
         OR aggregate_id=ANY($3::uuid[]))`,
      [request.merchant_id, request.customer_id, paymentIds],
    );
    await client.query(
      `UPDATE operations.analytics_events SET customer_id=NULL,anonymous_id=NULL,email=NULL,properties='{}'
       WHERE merchant_id=$1 AND customer_id=$2`,
      values,
    );
    await client.query(`DELETE FROM operations.notification_preferences WHERE merchant_id=$1 AND customer_id=$2`, values);
    await client.query(
      `UPDATE operations.notifications SET customer_id=NULL,destination='',payload='{}',last_error=NULL,updated_at=now()
       WHERE merchant_id=$1 AND customer_id=$2`,
      values,
    );
    await client.query(
      `UPDATE operations.email_deliveries
       SET customer_id=NULL,destination='',subject='Deleted customer notification',text_body='',html_body='',
           provider_response='{}',last_error=NULL,locked_by=NULL,locked_at=NULL,lease_expires_at=NULL
       WHERE merchant_id=$1 AND customer_id=$2`,
      values,
    );
    await client.query(
      `UPDATE operations.jobs SET payload='{}',last_error=NULL,locked_by=NULL,locked_at=NULL,lease_expires_at=NULL,
         status=CASE WHEN status='processing' THEN 'completed' WHEN status IN ('pending','retry') THEN 'completed' ELSE status END
       WHERE merchant_id=$1 AND (payload->>'customerId'=$2::text OR payload->>'paymentId'=ANY($3::text[]))`,
      [request.merchant_id, request.customer_id, paymentIds],
    );
    await client.query(
      `UPDATE operations.dead_letters SET payload='{}',error='redacted'
       WHERE payload->>'merchantId'=$1::text AND (payload->>'customerId'=$2::text
         OR payload->>'paymentId'=ANY($3::text[]))`,
      [request.merchant_id, request.customer_id, paymentIds],
    );
    await client.query(
      `UPDATE operations.idempotency_keys SET response_body=COALESCE(response_body,'{}') - 'customerId'
       WHERE merchant_id=$1 AND response_body->>'customerId'=$2::text`,
      values,
    );
    await client.query(`DELETE FROM operations.document_manifests WHERE merchant_id=$1 AND customer_id=$2`, values);
  }
}
