const sensitivePayloadKeys = new Set([
  'billingAddress', 'billingName', 'body', 'customerEmail', 'customerSnapshot', 'destination',
  'email', 'externalReference', 'metadata', 'name', 'phone', 'subject',
]);

function withoutPersonalData(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(withoutPersonalData);
  if (!value || typeof value !== 'object') return value;
  return Object.fromEntries(Object.entries(value as Record<string, unknown>)
    .filter(([key]) => !sensitivePayloadKeys.has(key))
    .map(([key, nested]) => [key, withoutPersonalData(nested)]));
